1. Crear un nuevo archivo de script y llamarlo "MatchChecker.cs". Agregarlo a la escena principal.
2. En MatchChecker.cs, crear un método que checa si hay matches en la grid:
```csharp
public class MatchChecker : MonoBehaviour
{
    public bool CheckForMatches()
    {
        foreach (GameObject gemObject in grid.Children())
        {
            Gem gem = gemObject.GetComponent<Gem>();
            // Checar con gemstones adyacentes
            if (CheckMatch(gem))
            {
                return true;
            }
        }
        return false;
    }

    bool CheckMatch(Gem gem)
    {
        // Checar con las gemstones adyacentes (arriba, abajo, izquierda, derecha)
        Gem adjacentGem;
        if (CheckMatchAbove(gem, out adjacentGem) || CheckMatchBelow(gem, out adjacentGem) || CheckMatchLeft(gem, out adjacentGem) || CheckMatchRight(gem, out adjacentGem))
        {
            return true;
        }
        return false;
    }

    bool CheckMatchAbove(Gem gem, out Gem adjacentGem)
    {
        adjacentGem = null;
        // Checar con la gemstone arriba
        Gem aboveGem = grid.GetChild(gem.transform.position.x, gem.transform.position.y + 1).GetComponent<Gem>();
        if (aboveGem != null && aboveGem.type == gem.type)
        {
            adjacentGem = aboveGem;
            return true;
        }
        return false;
    }

    // Otros métodos para checar con gemstones adyacentes (abajo, izquierda, derecha)
}
```
