class Queue:
    def __init__(self):
        self.s1 = []  # stack for enqueue
        self.s2 = []  # stack for dequeue

    def enqueue(self, item):
        self.s1.append(item)

    def dequeue(self):
        if not self.s2:
            while self.s1:
                self.s2.append(self.s1.pop())
        return self.s2.pop()

    def is_empty(self):
        return len(self.s1) == 0 and len(self.s2) == 0

    def size(self):
        return len(self.s1) + len(self.s2)

    def peek(self):
        if not self.s2:
            while self.s1:
                self.s2.append(self.s1.pop())
        return self.s2[-1]

# Example usage:
