```java
import org.jnpcap.*;

public class NetworkSniffer {
    public static void main(String[] args) {
        // Configuração do sniffer
        CaptureFilter filter = new CaptureFilter();
        filter.addEtherType(EtherType.IPv4); // Captura apenas pacotes IPv4
        CaptureHandle capture = new CaptureHandle();
        capture.setFilter(filter);

        // Abre a interface de rede para captura
        NetworkInterface ni = NetworkInterface.getByName("eth0"); // Substitua por sua interface de rede
        capture.open(ni, 65535, CaptureMode.PROMISC);

        // Loop para capturar pacotes
        while (true) {
            Packet packet = capture.nextPacket(); // Captura o próximo pacote
            if (packet != null) {
                // Processa o pacote (por exemplo, impressão da camada IP)
                int srcIp = packet.getSrcIp();
                int dstIp = packet.getDstIp();
                System.out.println("Pacote recebido: from " + srcIp + " to " + dstIp);
            }
        }
    }
}
```
