        // Check if the buyer has enough tokens
        require(msg.sender.balance >= optionPrices[address(this)][strategyId], "Insufficient tokens");

        // Update the buyer's balance and the strategy's owner
        msg.sender.transfer(optionPrices[address(this)][strategyId]);
        optionPrices[address(this)][strategyId] = 0;

        // Emit event for the sale of the option strategy
        emit SellOptionStrategy(msg.sender, address(this), strategyId);
    }

    // Function to stake tokens
    function stakeTokens(uint amount) public {
        // Check if the user has enough tokens
        require(msg.sender.balance >= amount, "Insufficient tokens");

        // Update the user's balance and the staker's balance
        msg.sender.transfer(amount);
        stakers[msg.sender] += amount;

        // Emit event for the addition of a stake
        emit StakeAdded(msg.sender, amount);
    }

    // Function to unstake tokens
    function unstakeTokens(uint amount) public {
        // Check if the user has enough stakes
        require(stakers[msg.sender] >= amount, "Insufficient stakes");

        // Update the user's balance and the staker's balance
        msg.sender.transfer(amount);
        stakers[msg.sender] -= amount;

        // Emit event for the removal of a stake
        emit StakeRemoved(msg.sender, amount);
    }
}
