// Definimos la estructura de un nodo del árbol binario
struct Node {
    int value;
    Node* left;
    Node* right;
};

// Función para insertar un nuevo nodo en el árbol binario
Node* insertNode(Node* root, int value) {
    if (root == nullptr) {
        root = new Node();
        root->value = value;
        root->left = nullptr;
        root->right = nullptr;
    } else if (value < root->value) {
        root->left = insertNode(root->left, value);
    } else if (value > root->value) {
        root->right = insertNode(root->right, value);
    }
    return root;
}

// Función para buscar un valor en el árbol binario
bool searchNode(Node* root, int value) {
    if (root == nullptr) {
        return false;
    } else if (value == root->value) {
        return true;
    } else if (value < root->value) {
        return searchNode(root->left, value);
    } else {
        return searchNode(root->right, value);
    }
}

// Función principal para probar el algortimo
