    Node* root = nullptr;

    // Insertamos algunos nodos en el árbol
    root = insertNode(root, 5);
    insertNode(root, 2);
    insertNode(root, 8);
    insertNode(root, 3);
    insertNode(root, 9);

    // Buscamos un valor en el árbol
    int value = 8;
    if (searchNode(root, value)) {
        std::cout << "Valor encontrado: " << value << std::endl;
    } else {
        std::cout << "Valor no encontrado" << std::endl;
    }

    return 0;
}
