```Python
import math

class Player:
    def __init__(self, name):
        self.name = name
        self.elo = 1200  # initial Elo score

    def rate(self, opponent):
        expected_score = 1 / (1 + math.pow(10, (opponent.elo - self.elo) / 400))
        actual_score = 1 if self.won else 0
        self.elo = self.elo + 32 * (actual_score - expected_score)


class Game:
    def __init__(self, player1, player2, winner):
        self.player1 = player1
        self.player2 = player2
        self.winner = winner

    def play(self):
        if self.winner == self.player1.name:
            self.player1.rate(self.player2)
            self.player2.rate(self.player1)
        elif self.winner == self.player2.name:
            self.player2.rate(self.player1)
            self.player1.rate(self.player2)
        else:
            raise Exception("Invalid winner specified")


def compute_elo_scores(tournament_results):
    players = {}
    for game in tournament_results:
        player1 = game.player1
        player2 = game.player2
        if player1.name not in players:
            players[player1.name] = Player(player1.name)
        if player2.name not in players:
            players[player2.name] = Player(player2.name)
        game.play()

    for player in players.values():
        print(f"{player.name} has an Elo score of {player.elo}")


# example usage
player1 = Player("Player 1")
player2 = Player("Player 2")
player3 = Player("Player 3")

game1 = Game(player1, player2, "Player 1")
game2 = Game(player2, player3, "Player 2")
game3 = Game(player3, player1, "Player 3")

tournament_results = [game1, game2, game3]

compute_elo_scores(tournament_results)
```

