```
import heapq

class FibonacciHeap:
    def __init__(self):
        self.nodes = []

    def insert(self, node, distance):
        self.nodes.append((distance, node))
        heapq.heapify(self.nodes)

    def get(self, node):
        for dist, node_id in self.nodes:
            if node_id == node:
                return dist
        return None

    def extract_min(self):
        return heapq.heappop(self.nodes)[1]

    def decrease_key(self, node, distance):
        for i, (dist, n) in enumerate(self.nodes):
            if n == node:
                self.nodes[i] = (distance, node)
                heapq._heapify(self.nodes, i)
                return
        raise ValueError("Node not found in heap")

def shortest_path_length(line_length, start, destination):
    unknown_points = FibonacciHeap()
    known_points = set()

    unknown_points.insert((start, 0))

    while True:
        current_node, current_distance = unknown_points.extract_min()

        if current_node == destination:
            return current_distance

        if current_node in known_points:
            continue

        known_points.add(current_node)

        for neighbor, length in line_length.get(current_node, {}).items():
            distance = current_distance + length
            if neighbor in known_points:
                continue
            unknown_points.decrease_key(neighbor, distance)

    return None

